//! Core logic for Resilience OS.
//!
//! This crate contains everything the TUI needs that is *not* rendering:
//! reading system state, detecting the account's security mode, loading the
//! application catalog generated by the NixOS modules, and launching programs
//! safely (fixed argv, never through a shell).
//!
//! Design rule: every function that touches the system has a pure parsing
//! counterpart that takes the raw file contents, so it can be unit-tested on
//! any host.

pub mod admin;
pub mod catalog;
pub mod config;
pub mod handbook;
pub mod launch;
pub mod mode;
pub mod network;
pub mod notes;
pub mod proc;
pub mod recovery;
pub mod status;

/// Version of the Resilience userland, taken from the Cargo workspace.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// Format a byte count with binary units, e.g. `42.3 GiB`.
pub fn human_bytes(bytes: u64) -> String {
    const UNITS: [&str; 6] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{bytes} B")
    } else {
        format!("{value:.1} {}", UNITS[unit])
    }
}

#[cfg(test)]
mod tests {
    use super::human_bytes;

    #[test]
    fn human_bytes_formats_units() {
        assert_eq!(human_bytes(0), "0 B");
        assert_eq!(human_bytes(1023), "1023 B");
        assert_eq!(human_bytes(1024), "1.0 KiB");
        assert_eq!(human_bytes(1536 * 1024 * 1024), "1.5 GiB");
    }
}
